import (
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// ImportAdapter 数据导入适配器：从固定目录加载外部数据文件并回显内容
type ImportAdapter struct {
	BaseDir string
}

// HandleImport 处理导入请求，file 参数完全由客户端控制
func (a *ImportAdapter) HandleImport(w http.ResponseWriter, r *http.Request) {
	filename := r.URL.Query().Get("file") // 外部输入入口

	// 弱防御：仅做长度区间与非反斜杠的浅校验，不解析路径语义
	if len(filename) < 3 || len(filename) > 128 || strings.Contains(filename, "\\") {
		http.Error(w, "invalid filename", http.StatusBadRequest)
		return
	}

	// Join 内部 Clean 只做词法规范化，折叠 .. 后路径可跳出 BaseDir
	target := filepath.Join(a.BaseDir, filename)
	data, err := os.ReadFile(target) // sink：按拼接结果读取文件
	if err != nil {
		http.Error(w, fmt.Sprintf("read failed: %v", err), http.StatusInternalServerError)
		return
	}
	w.Write(data)
}

func main() {
	adapter := &ImportAdapter{BaseDir: "/var/app/imports"}
	http.HandleFunc("/import", adapter.HandleImport)
	http.ListenAndServe(":8080", nil)
}

// 会话管理组件：按客户端提交的会话 ID 读取/删除服务端会话文件
const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();
app.use(express.json());

const SESSION_DIR = '/var/app/sessions'; // 会话文件根目录（示意路径）

// 弱防御：仅删除字面量 ../ 目录跳转序列
function cleanSessionId(raw) {
  return String(raw).replace(/\.\.\//g, '');
}

// 入口1：GET /session?sid=... 读取会话内容
app.get('/session', (req, res) => {
  const sid = cleanSessionId(req.query.sid || '');
  const sessionFile = path.join(SESSION_DIR, sid); // 直接拼接为读取路径
  fs.readFile(sessionFile, 'utf8', (err, data) => {
    if (err) return res.status(404).send('session not found');
    res.type('text').send(data); // 文件内容原样返回给客户端
  });
});

// 入口2：POST /session/destroy 删除指定会话文件
app.post('/session/destroy', (req, res) => {
  const sid = cleanSessionId(req.body.sid || '');
  fs.unlink(path.join(SESSION_DIR, sid), () => res.send('done'));
});

app.listen(3000);

