import os
import pymysql

# 关键字黑名单：拦截常见 SQL 注入特征
SQL_BLACKLIST = ["select", "union", "insert", "update", "delete",
                 "drop", "exec", "master", "--", ";", "/*", "*/", "xp_"]

def looks_safe(value):
    low = str(value).lower()
    for kw in SQL_BLACKLIST:
        if kw in low:
            return False
    return True

def quote_escape(value):
    # 转义单引号，防止注入
    return str(value).replace("'", "''")

def build_order_clause(field, direction):
    # direction 限定 asc/desc，防止排序方向注入
    if str(direction).lower() not in ("asc", "desc"):
        direction = "asc"
    return "ORDER BY " + str(field) + " " + str(direction)

def get_conn():
    return pymysql.connect(host="db.internal", user="report_svc",
                           password=os.environ["REPORT_DB_PWD"],
                           database="report", charset="utf8mb4")

def run_query(sql, params=None):
    conn = get_conn()
    try:
        cur = conn.cursor()
        cur.execute(sql, params)
        cols = [d[0] for d in cur.description]
        return [dict(zip(cols, row)) for row in cur.fetchall()]
    finally:
        conn.close()

package com.staticres.web;

import com.staticres.helper.helper;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.io.File;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

@RestController
@RequestMapping("/static")
public class main {
    private static final Path BASE = Paths.get("/var/www/static");

    @PostMapping("/upload")
    public String upload(@RequestParam("file") MultipartFile file) throws Exception {
        byte[] raw = file.getBytes();
        String preview = new String(raw, StandardCharsets.UTF_8);
        if (helper.looksMalicious(preview)) { return "rejected"; }
        Path target = BASE.resolve(file.getOriginalFilename()).normalize();
        if (!target.startsWith(BASE)) { return "forbidden"; }
        Files.write(target, raw);
        return helper.validateAndSummarize(target.toFile());
    }

    @GetMapping("/fetch")
    public String fetch(@RequestParam("name") String name) throws Exception {
        Path p = BASE.resolve(name).normalize();
        if (!p.startsWith(BASE)) { return "forbidden"; }
        return helper.validateAndSummarize(p.toFile());
    }

    @GetMapping("/import")
    public String importRemote(@RequestParam("url") String url) throws Exception {
        if (!url.matches("^https?://[\\w.-]+/.*")) { return "bad-url"; }
        InputStream in = new java.net.URL(url).openStream();
        File tmp = File.createTempFile("imp", ".xml");
        Files.copy(in, tmp.toPath(), StandardCopyOption.REPLACE_EXISTING);
        return helper.validateAndSummarize(tmp);
    }
}

package com.staticres.helper;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import java.io.File;
import java.util.regex.Pattern;

public class helper {
    // 伪装防御: 黑名单仅拦内联 ENTITY 与带内部子集的 DOCTYPE
    private static final Pattern ENTITY_BLACK = Pattern.compile("(?i)<!\\s*ENTITY");
    private static final Pattern DOCTYPE_RE = Pattern.compile("(?is)<!\\s*DOCTYPE[^>]*\\[");

    public static boolean looksMalicious(String text) {
        return ENTITY_BLACK.matcher(text).find() || DOCTYPE_RE.matcher(text).find();
    }

    public static String validateAndSummarize(File f) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
        dbf.setXIncludeAware(true);
        dbf.setExpandEntityReferences(true);
        DocumentBuilder db = dbf.newDocumentBuilder();
        Document doc = db.parse(f);
        Element root = doc.getDocumentElement();
        NodeList nl = doc.getElementsByTagName("summary");
        String out = nl.getLength() > 0 ? nl.item(0).getTextContent() : root.getTagName();
        return "ok:" + out;
    }
}

