import { exec, execFileSync } from 'child_process';
import fs from 'fs';
import path from 'path';

const TPL_DIR = '/var/mail-templates';

// 审计日志：仅打印并原样返回载荷（透传，无任何清洗）
export function auditLog(action, payload) {
  console.log(`[audit] ${action} ${JSON.stringify(payload)}`);
  return payload;
}

// 流 A：渲染模板并转为纯文本
export function renderTemplate(tplId, locale) {
  const safeName = path.basename(String(tplId));
  const file = path.join(TPL_DIR, safeName + '.html');
  const raw = fs.readFileSync(file, 'utf8');
  const txt = execFileSync('pandoc', ['-f', 'html', '-t', 'plain', file]);
  return `${String(txt)} [locale=${locale}]`;
}

// 流 B：导出模板压缩包
function stripBackticks(s) {
  return String(s).replace(/`/g, '');
}

export function exportTemplateBundle(bundleName) {
  const name = stripBackticks(bundleName);
  const out = `/tmp/bundles/${name}-${Date.now()}.zip`;
  exec(`zip -rq ${out} ${TPL_DIR} -x '*.log'`);
  return out;
}

// 流 C：按区域同步模板缓存
const ALLOWED_REGIONS = ['cn', 'eu', 'us'];
export function syncTemplateCache(region) {
  if (!ALLOWED_REGIONS.includes(region)) {
    throw new Error('region not allowed');
  }
  exec(`rsync -a ${TPL_DIR}/${region}/ /cache/${region}/`);
}

