"""运维控制台: 三个入口全部先防御再触达渲染 sink"""
import html
from helper import build_page, is_safe_token, run_cmd, sanitize_text

def handle_run(params):
    """入口1: host 白名单校验, 命令输出再转义"""
    host = params.get('host', '')
    if not is_safe_token(host):
        return build_page('参数错误', '主机名仅允许字母数字点横线下划线')
    out = run_cmd(['ping', '-c', '1', '--', host])
    return build_page('Ping 结果', html.escape(out, quote=True))

def handle_status(params):
    """入口2: service 白名单校验, 输出经 sanitize_text"""
    svc = params.get('service', '')
    if not is_safe_token(svc):
        return build_page('参数错误', '服务名不合法')
    out = run_cmd(['systemctl', 'status', '--', svc])
    return build_page('服务状态', sanitize_text(out))

def handle_report(params):
    """入口3: note 任意文本, 全量转义后渲染"""
    note = params.get('note', '')
    return build_page('运维备注', sanitize_text(note))

ROUTES = {'/run': handle_run, '/status': handle_status, '/report': handle_report}

def dispatch(path, params):
    handler = ROUTES.get(path)
    if handler is None:
        return build_page('404', '未知路径')
    return handler(params)

"""运维命令封装库: 白名单校验 + 参数化执行 + HTML 渲染"""
import html
import re
import subprocess

_TOKEN_RE = re.compile(r'[A-Za-z0-9._-]{1,64}')

def is_safe_token(value):
    """fullmatch 整串白名单: 拒绝尖括号引号空格换行等全部元字符"""
    if not isinstance(value, str) or not value:
        return False
    return _TOKEN_RE.fullmatch(value) is not None

def sanitize_text(value):
    """HTML 元素内容转义, quote=True 兼顾属性上下文"""
    return html.escape(value if isinstance(value, str) else str(value), quote=True)

def run_cmd(args):
    """列表传参 + shell=False, 不给命令注入任何入口"""
    try:
        proc = subprocess.run(args, shell=False, capture_output=True,
                              text=True, timeout=10, check=False)
    except subprocess.TimeoutExpired:
        return '命令超时'
    return proc.stdout or proc.stderr or '无输出'

def render_raw(title, body):
    """底层拼接不做转义, 调用方必须先完成 sanitize"""
    return '<section class="panel"><h2>' + title + '</h2><pre>' + body + '</pre></section>'

def build_page(title, body):
    """页面组装: 原样透传给 render_raw"""
    return '<html><body>' + render_raw(title, body) + '</body></html>'

