// 订单处理后台任务：读取订单导出归档并返回行数汇总
const ARCHIVE_ROOT = '/data/order-exports';
const app = express();
app.use(express.json());

interface OrderJob {
  jobId: string;
  archiveName: string; // 归档文件名，由调用方任意指定
}

// 入口1：手动重试接口，运营后台可提交任意 archiveName
app.post('/jobs/order/retry', (req, res) => {
  const job: OrderJob = req.body; // 外部输入入口
  const summary = runOrderJob(job);
  res.json({ jobId: job.jobId, summary });
});

// 入口2：队列消费者，消息体同样源自运营后台下发
export function onQueueMessage(raw: string): string {
  return runOrderJob(JSON.parse(raw));
}

function runOrderJob(job: OrderJob): string {
  // 直接拼接外部文件名，未过滤 ../ 等目录穿越序列
  const targetPath = ARCHIVE_ROOT + '/' + job.archiveName;
  const content = fs.readFileSync(targetPath, 'utf8'); // 任意文件读取
  return `${job.jobId}: ${content.split('\n').length} rows`;
}

